@lru_cache(None)
def polys(n):
    S=[sum(fac(i)*fac(k-i) for i in range(max(0,k-n),min(k,n)+1)) for k in range(2*n+1)]
    C=[sum(comb(k,i)*fac(i) for i in range(k+1))-S[k] for k in range(n+1)]
    assert C[:7]==[0,0,0,0,1,14,145] and min(C[4:])>0
    return C,S
@lru_cache(None)
def frozen(a,d):
    return F(a-1,d),J(a-1,d)
def de(t,P,W,d):
    # Discard the favorable prime-power sign in the analytic tail, for monotonicity.
    return ((P+K*W/t)*eu(-d*t)
            +(Q('1.000000147')+Q('2.515')/t)*eu(-t/2)
            +Q('1.78')*eu(-2*t/3)+Q('.074')*t*eu(s/2-t))
def end(a,j,z,n,d=D):
    a,z=Q(a),Q(z)
    assert a>n/d and a-1>=ANC[n][0] and a>=41
    C,S=polys(n)
    assert 0<=z<C[j]
    P,W=frozen(a,d)
    h1,h2=de(a-1,P,W,d),de(a,P,W,d)
    e=V(n,a)+h2
    loss=a**j*((a/(a-1))*h1+e*(2*H(n,a)+e))
    val=sum(Q(C[k])*a**(j-k) for k in range(j,n+1))-z
    tail=sum(Q(S[k])*a**(j-k) for k in range(n+1,2*n+1))
    assert h1<1
    return val-tail-loss

else:
    a=Q(559); j=21
    P=mass(D0,1)[-2][1]
    c=R.polys(40)[0]
    shifted_debit=a**j*a/(a-1)*P*el(-D0*(a-1))
    allowance=sum(Q(c[k])*a**(j-k) for k in range(j,41))
    assert shifted_debit>allowance
    print('matched B0: lower bound on shifted sufficient debit / available polynomial',
          float(shifted_debit/allowance),flush=True)
    for n in R.ANC:R.anchor(n)
    for n,lst in onsets.items():
        j=6 if n==20 else n//2+1
        for k,a in enumerate(lst,j):
            ray(a,k,100 if k==6 else 0,n)
    for n,a in [(20,546),(40,1096),(80,2197)]:
        ray(a,n,Q(R.polys(n)[0][n],2),n)
    for a,j,z in tails:ray(a,j,z,20)
    for a,j,z,n in [('171.85',6,100,20),('211.5',8,0,20),('1083.9',40,0,40),('2185.9',80,0,80)]:
        ray(a,j,z,n)
    ray(2889,80,0,80,D0)
    ray(2899,80,Q(R.polys(80)[0][80],2),80,D0)

